import csv,collections
d=collections.defaultdict(list)
for r in csv.DictReader(open('responses.csv')): d[r['number_set']].append((int(r['target']),int(r['rating'])))
print(len(d))
for s,v in sorted(d.items(),key=lambda x:-len(x[1])):
  t=collections.defaultdict(list)
  for a,b in v: t[a].append(b)
  print(s,len(v),' '.join(f'{a}:{sum(b)}/{len(b)}' for a,b in sorted(t.items())))
" | head -80

